 "content": "def transform(grid):
    """Replace each 3-cell with its horizontally mirrored counterpart."""
    out = [row[:] for row in grid]
    width = len(grid[0]) if grid else 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 3:
                out[r][c] = row[width - 1 - c]
    return out
